const invoices = $('Get Invoices').all().map(i => i.json);
const payments = $('Get Payments').all().map(i => i.json);

const normKey = (v) => String(v == null ? '' : v).toLowerCase().replace(/[^a-z0-9]/g, '');
const digitsOf = (v) => String(v == null ? '' : v).replace(/[^0-9]/g, '');
const toNum = (v) => {
  const n = Number(String(v == null ? '0' : v).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
};
const toDate = (v) => {
  const d = new Date(String(v));
  return isNaN(d.getTime()) ? null : d;
};

const similarity = (a, b) => {
  const s1 = normKey(a);
  const s2 = normKey(b);
  if (!s1.length && !s2.length) return 100;
  if (!s1.length || !s2.length) return 0;
  const dp = [];
  for (let i = 0; i <= s1.length; i++) { dp.push([i]); }
  for (let j = 1; j <= s2.length; j++) { dp[0][j] = j; }
  for (let i = 1; i <= s1.length; i++) {
    for (let j = 1; j <= s2.length; j++) {
      dp[i][j] = s1[i - 1] === s2[j - 1]
        ? dp[i - 1][j - 1]
        : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
    }
  }
  const maxLen = Math.max(s1.length, s2.length);
  return Math.round((1 - dp[s1.length][s2.length] / maxLen) * 100);
};

const openInvoices = invoices.filter(inv => inv.invoice_id && normKey(inv.status) !== 'paid');

const scorePair = (pay, inv) => {
  const reasons = [];
  let score = 0;
  const ref = normKey(pay.reference_text);
  const id = normKey(inv.invoice_id);
  const refDigits = digitsOf(pay.reference_text);
  const idDigits = digitsOf(inv.invoice_id);
  let idHit = false;

  if (id && ref.indexOf(id) !== -1) {
    score += 50; idHit = true; reasons.push('exact_invoice_id_in_reference');
  } else if (idDigits.length >= 3 && refDigits.indexOf(idDigits) !== -1) {
    score += 40; idHit = true; reasons.push('fuzzy_invoice_id_in_reference');
  }

  const payAmt = toNum(pay.amount);
  const invAmt = toNum(inv.amount);
  const variance = Math.round((payAmt - invAmt) * 100) / 100;
  const withinTolerance = invAmt > 0 && Math.abs(variance) / invAmt <= 0.02;

  if (invAmt > 0 && payAmt === invAmt) { score += 30; reasons.push('exact_amount'); }
  else if (withinTolerance) { score += 20; reasons.push('amount_within_2pct_tolerance'); }

  const nameScore = similarity(pay.sender_name, inv.customer_name);
  if (nameScore >= 90) { score += 15; reasons.push('customer_name_match_' + nameScore); }
  else if (nameScore >= 75) { score += 8; reasons.push('customer_name_partial_' + nameScore); }

  const pd = toDate(pay.date);
  const dd = toDate(inv.due_date);
  if (pd && dd && Math.abs(pd.getTime() - dd.getTime()) / 86400000 <= 15) {
    score += 5; reasons.push('within_due_date_window');
  }

  return { inv: inv, score: score, reasons: reasons, idHit: idHit, variance: variance, payAmt: payAmt, invAmt: invAmt, withinTolerance: withinTolerance, nameScore: nameScore };
};

const claimedBy = {};
const results = [];

for (const pay of payments) {
  if (!pay.transaction_id) { continue; }

  const scored = openInvoices.map(inv => scorePair(pay, inv));
  const idHits = scored.filter(s => s.idHit);
  scored.sort((a, b) => b.score - a.score);
  const best = scored.length ? scored[0] : null;

  let status = 'Unmatched';
  let matchedId = '';
  let matchedCustomer = '';
  let invoiceAmount = 0;
  let variance = 0;
  let score = best ? best.score : 0;
  let reasons = ['no_candidate_above_threshold'];

  if (idHits.length > 1) {
    const combinedTotal = idHits.reduce((t, s) => t + s.invAmt, 0);
    const ids = idHits.map(s => s.inv.invoice_id).join(' + ');
    status = 'Needs Review';
    matchedId = ids;
    invoiceAmount = combinedTotal;
    variance = Math.round((toNum(pay.amount) - combinedTotal) * 100) / 100;
    reasons = ['multiple_invoice_ids_in_reference', 'combined_invoice_total_' + combinedTotal, variance === 0 ? 'combined_total_matches_payment' : 'combined_total_variance_' + variance];
  } else if (best && best.score >= 50) {
    const invId = best.inv.invoice_id;
    matchedId = invId;
    matchedCustomer = best.inv.customer_name;
    invoiceAmount = best.invAmt;
    variance = best.variance;
    reasons = best.reasons.slice();

    if (claimedBy[invId]) {
      status = 'Duplicate';
      reasons.push('invoice_already_settled_by_' + claimedBy[invId]);
    } else if (best.idHit && !best.withinTolerance && best.payAmt < best.invAmt) {
      status = 'Partial';
      reasons.push('short_payment');
      claimedBy[invId] = pay.transaction_id;
    } else if (best.idHit && !best.withinTolerance && best.payAmt > best.invAmt) {
      status = 'Overpaid';
      reasons.push('excess_payment');
      claimedBy[invId] = pay.transaction_id;
    } else if (best.score >= 80) {
      status = 'Matched';
      claimedBy[invId] = pay.transaction_id;
    } else {
      status = 'Needs Review';
      reasons.push('confidence_below_auto_post_threshold');
    }
  }

  results.push({
    json: {
      transaction_id: pay.transaction_id,
      payment_date: pay.date,
      payment_amount: toNum(pay.amount),
      reference_text: pay.reference_text,
      sender_name: pay.sender_name,
      matched_invoice_id: matchedId,
      customer_name: matchedCustomer,
      invoice_amount: invoiceAmount,
      variance: variance,
      match_score: score,
      status: status,
      auto_post: status === 'Matched',
      match_reasons: reasons.join(' | '),
      reconciled_at: new Date().toISOString()
    }
  });
}

return results;

const rows = $input.all().map(i => i.json);
const total = rows.length;
const countOf = (s) => rows.filter(r => r.status === s).length;

const matched = countOf('Matched');
const partial = countOf('Partial');
const overpaid = countOf('Overpaid');
const duplicate = countOf('Duplicate');
const review = countOf('Needs Review');
const unmatched = countOf('Unmatched');
const exceptions = total - matched;

const autoMatchRate = total ? Math.round((matched / total) * 1000) / 10 : 0;
const exceptionRate = total ? Math.round((exceptions / total) * 1000) / 10 : 0;

const money = (n) => Number(n || 0).toLocaleString('en-US');
const reconciledAmount = rows.filter(r => r.status === 'Matched').reduce((t, r) => t + Number(r.payment_amount || 0), 0);
const flaggedAmount = rows.filter(r => r.status !== 'Matched').reduce((t, r) => t + Number(r.payment_amount || 0), 0);
const totalVariance = rows.reduce((t, r) => t + Number(r.variance || 0), 0);

const exceptionRows = rows.filter(r => r.status !== 'Matched');
let tableRows = '';
for (const r of exceptionRows) {
  tableRows += '<tr>'
    + '<td style="padding:6px 10px;border-bottom:1px solid #eee;">' + r.transaction_id + '</td>'
    + '<td style="padding:6px 10px;border-bottom:1px solid #eee;">' + (r.matched_invoice_id || '-') + '</td>'
    + '<td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:right;">' + money(r.payment_amount) + '</td>'
    + '<td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:right;">' + money(r.variance) + '</td>'
    + '<td style="padding:6px 10px;border-bottom:1px solid #eee;text-align:center;">' + r.match_score + '</td>'
    + '<td style="padding:6px 10px;border-bottom:1px solid #eee;"><b>' + r.status + '</b></td>'
    + '</tr>';
}
if (!tableRows) {
  tableRows = '<tr><td colspan="6" style="padding:10px;">No exceptions in this run.</td></tr>';
}

const statLine = (label, value) => '<tr><td style="padding:4px 10px;">' + label + '</td><td style="padding:4px 10px;text-align:right;"><b>' + value + '</b></td></tr>';

const html = '<div style="font-family:Arial,Helvetica,sans-serif;color:#222;max-width:760px;">'
  + '<h2 style="margin:0 0 4px 0;">Invoice Reconciliation Summary</h2>'
  + '<p style="margin:0 0 16px 0;color:#666;font-size:13px;">Run completed ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC</p>'
  + '<table style="border-collapse:collapse;font-size:14px;margin-bottom:20px;">'
  + statLine('Transactions processed', total)
  + statLine('Auto-matched', matched + ' (' + autoMatchRate + '%)')
  + statLine('Sent to exception queue', exceptions + ' (' + exceptionRate + '%)')
  + statLine('Partial payments', partial)
  + statLine('Overpayments', overpaid)
  + statLine('Duplicate payments blocked', duplicate)
  + statLine('Low-confidence / needs review', review)
  + statLine('Unidentified transactions', unmatched)
  + statLine('Amount reconciled', money(reconciledAmount))
  + statLine('Amount held for review', money(flaggedAmount))
  + statLine('Net variance', money(totalVariance))
  + '</table>'
  + '<h3 style="margin:0 0 8px 0;">Exception queue</h3>'
  + '<table style="border-collapse:collapse;font-size:13px;width:100%;">'
  + '<tr style="background:#f2f4f7;text-align:left;">'
  + '<th style="padding:8px 10px;">Transaction</th><th style="padding:8px 10px;">Invoice</th>'
  + '<th style="padding:8px 10px;text-align:right;">Paid</th><th style="padding:8px 10px;text-align:right;">Variance</th>'
  + '<th style="padding:8px 10px;text-align:center;">Score</th><th style="padding:8px 10px;">Status</th></tr>'
  + tableRows
  + '</table>'
  + '<p style="margin-top:18px;color:#666;font-size:12px;">Only exact, high-confidence matches are posted automatically. Everything else is held for human review rather than silently reconciled.</p>'
  + '</div>';

return [{
  json: {
    total_transactions: total,
    auto_matched: matched,
    exceptions: exceptions,
    auto_match_rate: autoMatchRate,
    exception_rate: exceptionRate,
    partial_payments: partial,
    overpayments: overpaid,
    duplicates_blocked: duplicate,
    needs_review: review,
    unmatched: unmatched,
    amount_reconciled: reconciledAmount,
    amount_held: flaggedAmount,
    net_variance: totalVariance,
    email_subject: 'Reconciliation Summary - ' + matched + '/' + total + ' auto-matched, ' + exceptions + ' exceptions',
    html_report: html
  }
}];
